/* prog17_whitespace_trim.c
 *
 * Behaviour (deduced from the original binary):
 *   • If no argument is supplied, prints "EMPTY".
 *   • Otherwise takes the first argument as a string, trims leading and
 *     trailing whitespace, collapses any internal run of whitespace
 *     to a single space, and prints the result.
 *   • The input is limited to the first 1024 characters; any characters
 *     beyond that are ignored.
 *   • If the resulting string is empty, prints "EMPTY".
 *
 * Whitespace characters considered are the same as the C library
 * function isspace(): space, '\t', '\n', '\v', '\f', '\r'.
 */

#include <stdio.h>
#include <string.h>
#include <ctype.h>

#define MAX_INPUT 1024

int main(int argc, char *argv[])
{
    /* No argument → EMPTY */
    if (argc < 2) {
        puts("EMPTY");
        return 0;
    }

    const char *src = argv[1];
    size_t src_len = strlen(src);
    if (src_len > MAX_INPUT)
        src_len = MAX_INPUT;               /* truncate to 1024 bytes */

    char out[MAX_INPUT + 1];               /* output buffer */
    size_t out_len = 0;

    size_t i = 0;

    /* Skip leading whitespace */
    while (i < src_len && isspace((unsigned char)src[i]))
        ++i;

    int in_space = 0;                      /* we are currently in a run of whitespace */

    for ( ; i < src_len; ++i) {
        unsigned char c = (unsigned char)src[i];

        if (isspace(c)) {
            in_space = 1;                  /* remember that we saw whitespace */
        } else {
            if (in_space && out_len > 0) {
                /* collapse previous whitespace run to a single space */
                out[out_len++] = ' ';
            }
            out[out_len++] = c;
            in_space = 0;
        }
    }

    /* Remove a trailing space if we ended on whitespace */
    if (out_len > 0 && out[out_len - 1] == ' ')
        --out_len;

    out[out_len] = '\0';

    if (out_len == 0)
        puts("EMPTY");
    else
        puts(out);

    return 0;
}
